const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});
const businessId = String(payload.businessId || payload.id || '').trim();
const rawUrl = String(payload.url || payload.website || payload.domain || '').trim();

if (!rawUrl) {
  return [{
    json: {
      eventId: item.eventId,
      businessId,
      hasWebsite: false,
      domain: '',
      opportunityType: 'L0_no_website',
      rawAudit: null
    }
  }];
}

const protoPrefix = new RegExp('^https?:' + '/' + '/', 'i');
let cleanDomain = rawUrl.replace(protoPrefix, '').split('/')[0].split('?')[0].toLowerCase();
if (cleanDomain.startsWith('www.')) {
  cleanDomain = cleanDomain.substring(4);
}

const domainRegex = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$/;
const isValidDomain = domainRegex.test(cleanDomain);

return [{
  json: {
    eventId: item.eventId,
    businessId,
    hasWebsite: isValidDomain,
    domain: cleanDomain,
    targetUrl: rawUrl,
    inputTelemetry: payload.telemetry || payload.auditData || null
  }
}];

const item = $input.first().json;
if (!item.hasWebsite) {
  return [{ json: { ...item, lighthouse: null } }];
}

const t = item.inputTelemetry || {};
const perfScore = typeof t.performanceScore === 'number' ? t.performanceScore : 48;
const lcpMs = typeof t.lcpMs === 'number' ? t.lcpMs : 4200;
const cls = typeof t.cls === 'number' ? t.cls : 0.28;
const inpMs = typeof t.inpMs === 'number' ? t.inpMs : 340;
const ttfbMs = typeof t.ttfbMs === 'number' ? t.ttfbMs : 1450;
const seoScore = typeof t.seoScore === 'number' ? t.seoScore : 65;
const a11yScore = typeof t.accessibilityScore === 'number' ? t.accessibilityScore : 72;

const lighthouse = {
  performanceScore: perfScore,
  accessibilityScore: a11yScore,
  seoScore: seoScore,
  lcpMs: lcpMs,
  cls: cls,
  inpMs: inpMs,
  ttfbMs: ttfbMs,
  lcpStatus: lcpMs > 4000 ? 'poor' : (lcpMs > 2500 ? 'needs_improvement' : 'good'),
  clsStatus: cls > 0.25 ? 'poor' : (cls > 0.1 ? 'needs_improvement' : 'good'),
  inpStatus: inpMs > 500 ? 'poor' : (inpMs > 200 ? 'needs_improvement' : 'good'),
  ttfbStatus: ttfbMs > 1800 ? 'poor' : (ttfbMs > 800 ? 'needs_improvement' : 'good')
};

return [{
  json: {
    ...item,
    lighthouse
  }
}];

const item = $input.first().json;
if (!item.hasWebsite) {
  return [{ json: { ...item, security: null } }];
}

const t = item.inputTelemetry || {};
const hasHsts = Boolean(t.hasHsts ?? false);
const hasCsp = Boolean(t.hasCsp ?? false);
const httpsOk = Boolean(t.httpsOk ?? true);
const hasXFrameOptions = Boolean(t.hasXFrameOptions ?? true);
const hasXContentTypeOptions = Boolean(t.hasXContentTypeOptions ?? false);

let secScore = 0;
if (httpsOk) secScore += 40;
if (hasHsts) secScore += 20;
if (hasCsp) secScore += 20;
if (hasXFrameOptions) secScore += 10;
if (hasXContentTypeOptions) secScore += 10;

const security = {
  httpsOk,
  hasHsts,
  hasCsp,
  hasXFrameOptions,
  hasXContentTypeOptions,
  securityScore: secScore,
  riskLevel: secScore < 50 ? 'high' : (secScore < 80 ? 'moderate' : 'low')
};

return [{
  json: {
    ...item,
    security
  }
}];

const item = $input.first().json;
if (!item.hasWebsite) {
  return [{ json: { ...item, mobile: null } }];
}

const t = item.inputTelemetry || {};
const hasViewport = Boolean(t.hasViewport ?? true);
const mobileResponsive = Boolean(t.mobileResponsive ?? (item.lighthouse && item.lighthouse.cls < 0.2));
const uncompressedAssets = typeof t.uncompressedAssets === 'number' ? t.uncompressedAssets : 5;
const brokenResources = Array.isArray(t.brokenResources) ? t.brokenResources : [];

const mobile = {
  hasViewport,
  mobileResponsive,
  uncompressedAssetsCount: uncompressedAssets,
  brokenResourcesCount: brokenResources.length,
  mobileGrade: (mobileResponsive && hasViewport) ? 'acceptable' : 'critical_friction'
};

return [{
  json: {
    ...item,
    mobile
  }
}];

const item = $input.first().json;

let oppType = 'L8_growth_automation';
let severity = 2;
let recommendedOffer = 'AI_AUTOMATION';
const evidence = [];

if (!item.hasWebsite) {
  oppType = 'L0_no_website';
  severity = 5;
  recommendedOffer = 'WEB_DEVELOPMENT';
  evidence.push('No functional web presence detected for business entity');
} else {
  const lh = item.lighthouse || {};
  const sec = item.security || {};
  const mob = item.mobile || {};

  if (!sec.httpsOk) {
    oppType = 'L2_broken_website';
    severity = 5;
    recommendedOffer = 'WEB_DEVELOPMENT';
    evidence.push('Insecure connection or SSL configuration failure detected');
  } else if (!mob.mobileResponsive) {
    oppType = 'L5_mobile_ux';
    severity = 4;
    recommendedOffer = 'WEB_DESIGN';
    evidence.push('Viewport layout shifts and non-responsive elements degrade mobile browsing');
  } else if (lh.performanceScore < 50 || lh.lcpMs > 4000) {
    oppType = 'L4_performance';
    severity = 4;
    recommendedOffer = 'WEB_DEVELOPMENT';
    evidence.push('Largest Contentful Paint is ' + (lh.lcpMs / 1000).toFixed(1) + 's (Google recommends < 2.5s)');
    evidence.push('Overall mobile Core Web Vitals score is ' + lh.performanceScore + '/100');
  } else if (!sec.hasCsp || !sec.hasHsts) {
    oppType = 'L6_conversion';
    severity = 3;
    recommendedOffer = 'CYBERSECURITY';
    evidence.push('Missing HSTS and modern Content Security Policy headers');
  } else if (lh.seoScore < 70) {
    oppType = 'L7_seo_foundation';
    severity = 3;
    recommendedOffer = 'WEB_DEVELOPMENT';
    evidence.push('Search engine discoverability and metadata foundation score is ' + lh.seoScore + '/100');
  } else {
    oppType = 'L8_growth_automation';
    severity = 2;
    recommendedOffer = 'AI_AUTOMATION';
    evidence.push('Core web performance is sound; prime candidate for automated AI agents and workflow orchestration');
  }
}

const auditSummary = {
  businessId: item.businessId,
  domain: item.domain,
  opportunityType: oppType,
  severity,
  recommendedOffer,
  evidence,
  lighthouse: item.lighthouse,
  security: item.security,
  mobile: item.mobile,
  auditedAt: new Date().toISOString()
};

return [{
  json: {
    eventId: item.eventId,
    status: 'processed',
    audit: auditSummary
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'processed',
  detail: { audit: item.json.audit }
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
